import (
	context "context"
	fern "github.com/go-allof-required-inherited/fern"
	fernclient "github.com/go-allof-required-inherited/fern/client"
)

client := fernclient.NewClient()
response, err := client.CreatePaymentSchedule(
	context.TODO(),
	&fern.ExternalPaymentScheduleRequest{
		StartDate: fern.MustParseDate(
			"2023-01-15",
		),
		Interval:             fern.PaymentScheduleIntervalWeekly,
		IntervalExecutionDay: 1,
	},
)

